{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@glaicer/supercode-skill-commands",
  "version": "0.3.0",
  "description": "OpenCode plugin that registers your agent skills as commands so they show up in / autocomplete",
  "type": "module",
  "license": "MIT",
  "author": "Dmitrii Aronov <aronov.mml@gmail.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Glaicer/supercode-skill-commands.git"
  },
  "homepage": "https://github.com/Glaicer/supercode-skill-commands#readme",
  "bugs": "https://github.com/Glaicer/supercode-skill-commands/issues",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "slash-commands"
  ],
  "main": "./skill-commands.js",
  "exports": {
    ".": "./skill-commands.js"
  },
  "files": [
    "skill-commands.js"
  ],
  "publishConfig": {
    "access": "public"
  }
}
